            total_metric_value += order
            instances_tested += 1
            n_max = max(n_max, n)

    return {
        "metric_name": "Order of Automorphism Group",
        "metric_value": total_metric_value / instances_tested,
        "instances_tested": instances_tested,
        "n_max": n_max,
        "conjecture_holds": conjecture_holds,
